def size_mcp_mux_fleet(qps: int = 300_000, rtt_sec: float = 0.180, burst: int = 3, pods: int = 120) -> dict:
    active_slots = qps * rtt_sec
    burst_slots = int(active_slots * burst)
    per_pod = burst_slots // pods
    return {"active_slots": int(active_slots), "burst_slots": burst_slots, "streams_per_pod": per_pod}

