def size_stdio_and_session_state(microvms: int = 25_000, vm_ram_mb: int = 128, sse_sessions: int = 10_000_000) -> dict:
    vm_ram_tb = (microvms * vm_ram_mb) / (1024 * 1024)
    session_gb = (sse_sessions * 4) / (1024 * 1024)
    return {"firecracker_tb": round(vm_ram_tb, 2), "redis_session_gb": round(session_gb, 1)}

def mint_downscoped_token(vault_client, user_jwt: str, agent_svid: str, target_audience: str, scope: str) -> str:
    if not user_jwt or not agent_svid:
        raise PermissionError("Both User JWT and Agent SPIFFE SVID are required")
    return vault_client.rfc8693_exchange(
        subject_token=user_jwt, actor_token=agent_svid,
        audience=target_audience, scope=scope, ttl_sec=60
    )

def enforce_firewall_pipeline(resp: dict, max_bytes: int, pii_automaton, deberta_fn) -> dict:
    raw = str(resp).encode("utf-8")[:max_bytes].decode("utf-8", errors="ignore")
    scrubbed = pii_automaton.redact(raw)
    if deberta_fn(scrubbed) > 0.85:
        raise SecurityError("Prompt injection detected in tool output")
    return {"sanitized_xml": f"<tool_data>{scrubbed}</tool_data>"}

def handle_sandbox_oom(session_id: str, vm_pool, max_retries: int = 1) -> str:
    for attempt in range(max_retries + 1):
        try:
            return vm_pool.restore_snapshot(session_id, timeout_ms=125)
        except TimeoutError:
            if attempt == max_retries:
                raise RuntimeError(f"Firecracker respawn failed for {session_id}")
